import{c as e,Q as a,j as o,m as l}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse(`{"title":"How to Prompt Claude Fable 5. Anthropic's playbook, decoded.","description":"","frontmatter":{"url":"https://x.com/kingwilliam_/status/2072735773980250287","title":"How to Prompt Claude Fable 5. Anthropic's playbook, decoded.","author":"kingwilliam_","archived":"2026-07-03T00:00:00.000Z","handle":"@kingwilliam_","published":"2026-07-02T00:00:00.000Z","stats":"46 likes · 5 retweets · 93 bookmarks · 40676 views","tags":["fable5","prompt-engineering","loop","barbell-strategy","skills","memory"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@kingwilliam_-250287.md","filePath":"research/tweets/2026-07-02-@kingwilliam_-250287.md","lastUpdated":1785909234000}`),i={name:"research/tweets/2026-07-02-@kingwilliam_-250287.md"};function s(n,t,r,d,p,c){return a(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="how-to-prompt-claude-fable-5-anthropic-s-playbook-decoded-—-kingwilliam" tabindex="-1">How to Prompt Claude Fable 5. Anthropic&#39;s playbook, decoded. — @kingwilliam_ <a class="header-anchor" href="#how-to-prompt-claude-fable-5-anthropic-s-playbook-decoded-—-kingwilliam" aria-label="Permalink to &quot;How to Prompt Claude Fable 5. Anthropic&#39;s playbook, decoded. — @kingwilliam_&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/kingwilliam_/status/2072735773980250287" target="_blank" rel="noreferrer">https://x.com/kingwilliam_/status/2072735773980250287</a><strong>作者</strong>：kingwilliam_（@kingwilliam_） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：46 likes · 5 retweets · 93 bookmarks · 40676 views</p><hr><h2 id="全文-核心要點" tabindex="-1">全文（核心要點） <a class="header-anchor" href="#全文-核心要點" aria-label="Permalink to &quot;全文（核心要點）&quot;">​</a></h2><p><strong>核心重新定位</strong>：Fable = 管理 team 的 lead，不再是聊天機器人。</p><p><strong>11 條核心規則</strong>：</p><ol><li>Fable 是 manager，不是 chatbot（可管理 50+ subagents）</li><li>Effort 對齊任務：low/medium = 簡單問答；high = 日常工作（默認）；xhigh = 最難問題；ultracode = 完全自主</li><li>給 why，不只給 what（Fable 需要意圖連接上下文）</li><li>保持 prompt 短（過度工程化反而降低輸出質量）</li><li>四要素結構：Context / Request / Output format / Constraints</li><li>設置 Checkpoint（暫停條件：只在花錢/發送外部內容/需要人決策時）</li><li>Loop 工程：<code>/goal</code> 跑到完成；<code>/loop</code> 定時循環</li><li><strong>Barbell strategy</strong>（= 10-80-10）：Fable 計劃（10%）→ 便宜模型執行（80%）→ Fable 驗證（10%）</li><li>建立 Context 系統（4步：<code>/claude-context/</code> 文件夾 + <code>claude-memory.md</code> 自更新 + <code>claude-instructions.md</code> + <code>/add</code> 連接）</li><li>把重複工作轉為 Skills（三種建法：從過去聊天提取/從頭構建/從數據訓練）</li><li>注意事項：舊 prompt 會讓 Fable 更差；早停時說「go ahead and do it end-to-end」</li></ol><p><strong>Checkpoint prompt</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run this end-to-end on your own and take as long as you need.</span></span>
<span class="line"><span>Pause for me only when it genuinely matters: spending money, sending</span></span>
<span class="line"><span>something external, or a call only I can make.</span></span>
<span class="line"><span>Otherwise don&#39;t stop, and show me the finished work when it&#39;s done.</span></span></code></pre></div><p><strong>Memory 四步</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Step 1: /claude-context/ 文件夾（who/SOPs/client docs/decisions log）</span></span>
<span class="line"><span>Step 2: claude-memory.md + 規則「Every time I give you major context, update claude-memory.md.」</span></span>
<span class="line"><span>Step 3: claude-instructions.md（standing brief）</span></span>
<span class="line"><span>Step 4: /add 或 CLAUDE.md 指向文件夾</span></span></code></pre></div><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Fable 5 Anthropic 官方 playbook 解碼：11 條規則涵蓋 Effort 選擇/四要素結構/Barbell strategy/Loop/Memory 四步建設/Skills 三種建法。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>Fable 是 manager 角色轉變，停止微觀管理，開始目標委派</li><li>短 prompt 優於長 prompt（反直覺）</li><li>Barbell strategy = 10-80-10（與 milesdeutscher 相同框架，不同命名）</li><li>Memory 系統四步可立即實施</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Effort 五段：low/medium/high/xhigh/ultracode</li><li><code>/goal</code> / <code>/loop</code> / <code>/loop stop [name]</code></li><li>Memory path：<code>/claude-context/</code> + <code>claude-memory.md</code></li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>與 wquguru、milesdeutscher 重疊度高（四要素、10-80-10、Loop）</li><li>「Anthropic&#39;s playbook, decoded」說法誇大，無具體 Anthropic 文件引用</li><li>Memory 四步的 self-update 機制（claude-memory.md 自動更新規則）是有價值的具體實踐</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6.5/10</td><td>Memory 四步和 checkpoint prompt 可直接用，但多有重疊</td></tr><tr><td>B. 創新性 (20%)</td><td>5.5/10</td><td>Barbell strategy 是 10-80-10 換名，技術內容重疊高</td></tr><tr><td>C. 證據品質 (20%)</td><td>5/10</td><td>聲稱解碼 Anthropic playbook 但無具體引用</td></tr><tr><td>D. 技術深度 (15%)</td><td>6/10</td><td>Skills 三建法和 Memory 四步有具體操作步驟</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>框架適用性廣，寫法易讀</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.0/10</strong></td><td>6.5×0.3+5.5×0.2+5×0.2+6×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Memory 四步自更新機制和 checkpoint prompt 模板可補充 MEMORY.md 操作規範；整體與已收錄文章重疊高，邊際價值有限。</p>`,24)])])}const g=e(i,[["render",s]]);export{m as __pageData,g as default};
